#include "laksa-mlir/Target/EmitHLSToHLSProfileScript/HLSProfileScriptEmitter.h"

using namespace mlir;
using namespace mlir::emithls;

LogicalResult emithls::translateEmitHLSToHLSProfileScript(
    ModuleOp,
    raw_ostream &os)
{
    os << R"SCRIPT(#!/bin/sh

# Generated by ladle -t emithls-to-hls-profile-script.

set -eu

script_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
profiles_dir="$script_dir/../profiles"
mkdir -p "$profiles_dir"

exec laksa-extract-hls-profile \
    "$script_dir" \
    --processor-type K26_PL \
    -o "$profiles_dir/profiles_K26_PL_hls.yaml"
)SCRIPT";
    return success();
}
